/* OPTRULES-BEGIN — generated by build_options_rules.py from BOOKS-RULES-OPTIONS.md + books-rules-stocks-addendum-20261113.md */
window.OPT_RULES = {"built": "2026-11-13", "options": [{"id": "A1", "sec": "(a) Market context / regime", "rule": "IV rank filter first. Rank today's IV against its own trailing ~2-year range (deciles 1–10). Bottom deciles: buying premium is OK. Top deciles: don't buy naked premium; use spreads or premium-selling structures.", "src": "Kaeppel, Option Trader's Guide, Ch.6 Volatility, PDF p.84 & p.87", "quote": "“Buying premium when volatility is high and selling premium when volatility is low are low-probability trades, as they put the odds immediately against you.” (p.87)"}, {"id": "A2", "sec": "(a) Market context / regime", "rule": "Strategy matrix. Directional + low IV → buy a call/put (or backspread). Directional + high IV → sell a vertical on the opposite side (e.g., bullish = sell a put spread). Neutral + low IV → calendar/straddle. Neutral + high IV → butterfly/covered call.", "src": "Kaeppel Ch.11, Table 11.1, PDF p.146", "quote": "“Low Volatility … Buy a naked call or put … High Volatility … Sell a vertical spread”"}, {"id": "A3", "sec": "(a) Market context / regime", "rule": "VIX regime (“stages of skew”). VIX ~16–18 with flat skew = Calm. Low IV with rising put skew = Calm before the storm. VIX 30–40+ = Typhoon (panic; ATM IV spikes, skew flattens). VIX 20–35 and falling = Calming storm (puts at their most expensive). Pick structure by stage: buy premium in Calm; avoid buying OTM puts in the Calming storm.", "src": "Chen & Sebastian, Option Trader's Hedge Fund, Ch.11, PDF p.160–162", "quote": "“there is extreme fear in the market and the VIX is at 30% to 40% or greater … This is a condition of borderline panic.” (p.162)"}, {"id": "A4", "sec": "(a) Market context / regime", "rule": "IV mean-reverts. Don't buy OTM vol in a crash. When IV is far above its mean, treat it as an overpriced sale unless there's a known event explaining it.", "src": "Chen & Sebastian Ch.4, PDF p.64–65", "quote": "“One of the worst trades in the world is to buy VIX OTM calls in the middle of a crash.” (p.64)"}, {"id": "A5", "sec": "(a) Market context / regime", "rule": "Event calendar before every trade (CPI, Fed, jobs data, big earnings). Know that the event is coming, even with no opinion on it.", "src": "Chen & Sebastian Ch.4, PDF p.63", "quote": "“he did not need to have an opinion on a company’s earnings … but he did need to know that the event was coming up.”"}, {"id": "A6", "sec": "(a) Market context / regime", "rule": "Higher time frame first (top-down). Read the daily/60-min structure before acting on 5-min signals. Don't take a with-trend entry into higher-time-frame overextension.", "src": "Candlestick Trading Bible, PDF p.70–71; Grimes, Art & Science of TA, Ch.7, PDF p.202–203", "quote": "“begin with bigger time frames to get the big picture, and then you switch to the smaller one” (CTB p.70)"}, {"id": "A7", "sec": "(a) Market context / regime", "rule": "Classify the day early with the IB. On a normal day about 85% of the range is set in the IB (first hour, 8:30–9:30 AM CT for SPY). Range extension of more than ~2× the IB = trend day (longer-term traders in control): don't fade it.", "src": "CBOT Market Profile Study Guide, Part I, PDF p.12, 15, 17", "quote": "“On normal days, 85% or more of the range is formed in the initial balance period.” (p.15) / “If the range extension is considerably more than double the initial balance area, the longer-term trader is in control.” (p.17)"}, {"id": "A8", "sec": "(a) Market context / regime", "rule": "Open vs. prior value. Buying above yesterday's VA or selling below it is initiating (strong). Buying below or selling above it is responsive (fade-type). An open outside prior value that holds = trend bias.", "src": "CBOT MP Guide Part III, PDF p.48; Fromhertz MarketWebs p.3 pts 2 & 5", "quote": "“Buying above value is unexpected; it is initiating activity … Generally, unexpected or initiating activity is stronger” (CBOT p.48) / “If price starts a new period above (or below) value, it is trending.” (MW p.3)"}, {"id": "A9", "sec": "(a) Market context / regime", "rule": "Inside value = range/chop. Outside value = trend. Don't use breakout tactics while price is inside the day/week VA.", "src": "MarketWebs, PDF p.3 pts 1–2", "quote": "“When price is inside value for a period it is range bound and not trending”"}, {"id": "A10", "sec": "(a) Market context / regime", "rule": "Index intraday trends are short. Expect SPY intraday trends to run about 3 legs at most. After the 3rd push, take profits rather than initiate.", "src": "Grimes Ch.6, PDF p.147", "quote": "“it is somewhat unusual for most intraday index products to have trends that extend more than three legs”"}, {"id": "A11", "sec": "(a) Market context / regime", "rule": "Equities mean-revert in the short term, except out of volatility compression. Favor fades at extremes. Favor breakouts only after inside bars or a tight range.", "src": "Grimes Ch.1, PDF p.36; Ch.10, PDF p.267", "quote": "“Even if the normal expectation for a market is mean reversion … there is usually at least a slight edge for continuation out of areas of volatility compression.” (p.36)"}, {"id": "A12", "sec": "(a) Market context / regime", "rule": "Market vs. catalyst. Ask whether a name is moving with the market or on its own catalyst. For SPY, the \"catalyst\" is the macro/event calendar.", "src": "Aziz, How to Day Trade for a Living, Ch.2 (part0004), Rule 4", "quote": "“Always ask, ‘Is this stock moving because the overall market is moving, or is it moving because it has a unique catalyst?’”"}, {"id": "A13", "sec": "(a) Market context / regime", "rule": "Regime and stops (Chan). News-driven moves = momentum regime, where stops help. Range/mean-reverting tape = tight stops get chopped. Size smaller and use structure-based stops there.", "src": "Chan, Quantitative Trading, Ch.6, PDF p.128", "quote": "“when the movement of prices is due to news or other fundamental reasons … one is likely to be in a momentum regime”"}, {"id": "B1", "sec": "(b) Setups and entry triggers", "rule": "Pullback only in a real trend. The setup leg into the pullback must be at least as strong as prior legs, with no momentum divergence. Enter on a washout below the pullback's support/channel that recovers within a few bars, or buy against support.", "src": "Grimes Ch.6 Pullback, PDF p.147–148", "quote": "“The most important condition for this trade is that the market must be trending.” (p.147)"}, {"id": "B2", "sec": "(b) Setups and entry triggers", "rule": "Skip pullbacks with 3+ tests of support (lower highs into support = likely failure).", "src": "Grimes Ch.6, PDF p.149", "quote": "“One pattern to avoid is buying against multiple (three or more) tests of support in a pullback”"}, {"id": "B3", "sec": "(b) Setups and entry triggers", "rule": "Failure test (Wyckoff spring/upthrust, “2B”). Price trades through a clear level (prior-day high/low, IB extreme, VA edge) and closes back inside on the same or next bar. Enter on that close, stop just beyond the extreme. It should work within 1–3 bars. If it stalls near the level, cut it.", "src": "Grimes Ch.6 Failure Test, PDF p.143–145", "quote": "“Enter short on the close of the bar that closes back below resistance.” (p.143) / “the trade should be immediately profitable (within one to three bars on the trading time frame).” (p.145)"}, {"id": "B4", "sec": "(b) Setups and entry triggers", "rule": "Breakouts: enter in the base, not the spike. Best breakouts come from a tight range near resistance or higher lows into resistance. Position inside the base.", "src": "Grimes Ch.6 Breakouts, PDF p.167–169", "quote": "“Positioning in this prebreakout base allows us to avoid having to play in the extreme volatility of the breakout itself.” (p.169)"}, {"id": "B5", "sec": "(b) Setups and entry triggers", "rule": "Opening-range break = trend-day tell. A gap down that presses lower or breaks below the opening range often trends all day. Dump longs and don't fade it. Mirror for upside.", "src": "Grimes Ch.8, PDF p.230", "quote": "“if the market opens down and immediately presses lower, or breaks lower out of an opening range, there is a good chance that it could trend down all day.”"}, {"id": "B6", "sec": "(b) Setups and entry triggers", "rule": "Let the open settle. Wait out the opening noise. Aziz waits ~10 min before acting on the open; many day traders wait until 10:00 ET (9:00 CT). [project: no entries 8:30–8:40 CT except a defined ORB/failure-test trigger]", "src": "Aziz Ch.8 (part0010_split_002); Sincere & Wagner, After-Hours Trader, PDF p.33", "quote": "“I looked at the chart and decided to wait and see the price action for 10 minutes at the beginning of trading.” (Aziz) / “many day traders wait until at least 10:00 a.m. before they enter their first order.” (AHT p.33)"}, {"id": "B7", "sec": "(b) Setups and entry triggers", "rule": "VWAP = who's in control. Above VWAP = buyers; below = sellers. Long trigger: price respects or reclaims VWAP. Buy as close to VWAP as possible. Stop on a 5-min close back below VWAP. Mirror for puts.", "src": "Aziz Ch.7 VWAP Trading (part0009_split_006)", "quote": "“When stock is traded above VWAP, it means that the buyers are in overall control” / “My stop will be a break and close 5-minute chart below VWAP.”"}, {"id": "B8", "sec": "(b) Setups and entry triggers", "rule": "Moving-average trend ride. In a clean trend respecting the 9 or 20 EMA on the 1–5 min chart, enter on a hold of the EMA and exit on a break. Use the 50/200 SMA as higher-level S/R.", "src": "Aziz Ch.7 Moving Average Trend Trading (part0009_split_005)", "quote": "“I use 9 and 20 exponential moving averages (EMA) and 50 and 200 simple moving averages (SMA).”"}, {"id": "B9", "sec": "(b) Setups and entry triggers", "rule": "Horizontal levels > diagonals. Mark prior-day high/low and round/half numbers before the open. Enter on an indecision candle at the level, with a stop on a 5-min close through it.", "src": "Aziz Ch.7 Support or Resistance (part0009_split_007)", "quote": "“the market doesn’t know diagonals. It remembers price levels” / “Half-dollars and whole dollars usually act at a support or resistance level.”"}, {"id": "B10", "sec": "(b) Setups and entry triggers", "rule": "Market Profile levels as triggers. Treat the prior VA high/low (TOV/BOV) and POC as S/R. A VA edge flips from resistance to support once price is accepted above it. The POC acts as a magnet. Untouched (virgin) POCs pull price when it's outside value.", "src": "MarketWebs PDF p.3 pts 3, 4, 6, 7, 11; CBOT MP Guide PDF p.11", "quote": "“Once price climbs above value, that pivot level will become support” / “The point of control will often act as a magnet”"}, {"id": "B11", "sec": "(b) Setups and entry triggers", "rule": "80% rule. If price opens/establishes outside the prior VA, then re-enters and is accepted inside it, expect a traverse to the other side of the VA (~80% per the source). Target = opposite VA edge. Invalid if the VA was already fully explored.", "src": "MarketWebs PDF p.3 pt 8", "quote": "“Once price enters a value area (and has established itself inside value) it has an 80% chance of passing from one side of value to the other.”"}, {"id": "B12", "sec": "(b) Setups and entry triggers", "rule": "Candles confirm; they don't trigger alone. Pin bar, engulfing or inside bar counts only at a key level (VWAP, VA edge, prior-day H/L, 21-MA, 50–61.8% retrace) and in line with the higher-time-frame trend. Enter after the candle closes.", "src": "Candlestick Trading Bible PDF p.19, p.96, p.159", "quote": "“Don’t try to trade the market using this price action setup alone, because you will need other factors of confluence” (p.19)"}, {"id": "B13", "sec": "(b) Setups and entry triggers", "rule": "No raw 5-min candle patterns. The author says 5-min pin/engulfing signals lose money (noise). For SPY intraday, require the pattern on the 15-min or 60-min chart, or on 5-min only when it sits on a B10/B7 level. [project translation of the book's 1H/4H/daily advice]", "src": "Candlestick Trading Bible PDF p.70, p.83, p.146", "quote": "“if you try to trade pin bars or engulfing bars on the 5-minute time frame, you will lose your money, because there is lot of noise” (p.70)"}, {"id": "B14", "sec": "(b) Setups and entry triggers", "rule": "Pin bar spec: long tail ≥ 2× body, rejecting a level. Stop beyond the tail. Target the next S/R. A conservative entry at a 50% retrace of the pin's range gives better R:R but sometimes misses.", "src": "Candlestick Trading Bible PDF p.37, p.92–95", "quote": "“the shadow should be twice the length of the real body” (p.37) / “your stop loss above the long tail. your profit target will be the next support level” (p.93)"}, {"id": "B15", "sec": "(b) Setups and entry triggers", "rule": "Timing edge must be measured. For long calls/puts, test the trigger as “% of time the underlying is higher (lower) N days/hours later.” A trigger without a measured hit rate isn't a setup.", "src": "Kaeppel Ch.8, PDF p.114", "quote": "“if you develop an entry criterion for buying calls and find that 70% of the time the underlying security is higher 5 days later, you have a very powerful tool”"}, {"id": "B16", "sec": "(b) Setups and entry triggers", "rule": "Indicators indicate; price levels decide. Never trade a pure indicator signal (RSI, MACD cross).", "src": "Aziz Ch.7 (part0009_split_008), Rule 10; Grimes Ch.1, PDF p.19", "quote": "“Indicators only indicate; they should not be allowed to dictate.”"}, {"id": "C1", "sec": "(c) Options structure: IV, probability, strike/delta, DTE, spreads", "rule": "Buy delta ≥ 0.50 (ATM to ITM), not cheap OTM. Delta ≈ rough chance of finishing in the money. A 0.33-delta call is about a 1-in-3 shot, held to expiry.", "src": "Kaeppel Ch.12, PDF p.155; Ch.7, PDF p.103, p.110", "quote": "“Purchase options with a delta of 50 or more (for calls) and a delta of –50 or less (for puts).” (p.155) / “if you buy a call option with a delta of 33, you have only about a 1:3 chance of breaking even” (p.110)"}, {"id": "C2", "sec": "(c) Options structure: IV, probability, strike/delta, DTE, spreads", "rule": "The higher the IV, the deeper ITM and the shorter-term the option you buy (less extrinsic exposed to IV crush).", "src": "Kaeppel Ch.12, PDF p.155", "quote": "“the higher the implied volatility, the further in the money and the shorter term the option you buy should be.”"}, {"id": "C3", "sec": "(c) Options structure: IV, probability, strike/delta, DTE, spreads", "rule": "Buy options made mostly of intrinsic value. Sell options made of pure time value.", "src": "Kaeppel Ch.10 Summary, PDF p.142–143", "quote": "“Buy options with little time premium. • Write options that are all time premium.”"}, {"id": "C4", "sec": "(c) Options structure: IV, probability, strike/delta, DTE, spreads", "rule": "Time decay accelerates into expiry; book DTE for naked longs is ≥ 30. Kaeppel wants ≥30 DTE for naked buys and warns about the final ~2 weeks (PROVEST table). For Atlas's 0–7 DTE: only valid if the hold is short (minutes–hours for 0–1 DTE; ≤1–2 days for 2–7 DTE) and the strike is ≥ 0.50 delta. [project]", "src": "Kaeppel Ch.5, PDF p.72; Ch.12, PDF p.155; App. A Table A.2, PDF p.267", "quote": "“The rate at which the time premium in an option price decays accelerates as expiration draws nearer.” (p.72) / “Buy options with at least 30 days (and preferably more) until expiration.” (p.155)"}, {"id": "C5", "sec": "(c) Options structure: IV, probability, strike/delta, DTE, spreads", "rule": "Match DTE to the expected holding window. A defined short window (e.g., ≤5 days) cuts IV and decay worries if you don't buy options with only days left. So for a 1–3 day swing, prefer 7–14 DTE over 0–3 DTE. [project: DTE ≥ ~3× intended hold]", "src": "Kaeppel Ch.8, PDF p.115", "quote": "“as long as you don’t buy options with less than a few weeks until expiration, you don’t need to concern yourself as much with time decay.”"}, {"id": "C6", "sec": "(c) Options structure: IV, probability, strike/delta, DTE, spreads", "rule": "Never hold long premium into a weekend you don't need. Market makers price out the weekend's decay by Friday. If a trade is near its exit on Friday afternoon, close it. There's no \"weekend edge\" either way.", "src": "Chen & Sebastian Ch.12, PDF p.169–171", "quote": "“If you are in an option trade on the cusp of exit on a Friday afternoon, get out of the position.” (p.170)"}, {"id": "C7", "sec": "(c) Options structure: IV, probability, strike/delta, DTE, spreads", "rule": "Assess probability before entry, then manage in dollars. After entry, the starting probability no longer matters. Exits are price/$-based.", "src": "Kaeppel Ch.7, PDF p.110", "quote": "“Once a trade is entered, it must be managed on the basis of dollars and cents, not probability.”"}, {"id": "C8", "sec": "(c) Options structure: IV, probability, strike/delta, DTE, spreads", "rule": "High IV + directional view → vertical spread. Long-premium alternative: a debit spread that sells the richer OTM leg (skew). Premium-selling alternative: a credit vertical on the opposite side.", "src": "Kaeppel Ch.6 Skew, PDF p.87–88; Ch.16, PDF p.207; Chen Ch.10 Table 10.1, PDF p.142", "quote": "“a trader might consider buying an at-the-money put option … and simultaneously writing an out-of-the-money put option … which is trading at a higher volatility.” (Kaeppel p.88)"}, {"id": "C9", "sec": "(c) Options structure: IV, probability, strike/delta, DTE, spreads", "rule": "Credit spread risk rule. Cap the loss at ≈ max profit (≤ 1.2×). Place the stop beyond a real support/resistance level. Take profit at ~80% of max credit.", "src": "Kaeppel Ch.16, PDF p.211–213", "quote": "“You don’t want to risk much more than your maximum profit potential on the trade.” (p.213) / “We will take our profit if we reach 80% of the maximum profit potential” (p.212)"}, {"id": "C10", "sec": "(c) Options structure: IV, probability, strike/delta, DTE, spreads", "rule": "Don't be married to a delta or a width. Sell the strike/width that's richest on the skew. Know your IV-equivalent limit price and use vega to set how far you'll concede.", "src": "Chen & Sebastian Ch.4, PDF p.67–68", "quote": "“The key is to not be married to delta or percentage out-of-the-money.” (p.67)"}, {"id": "C11", "sec": "(c) Options structure: IV, probability, strike/delta, DTE, spreads", "rule": "Changes in IV hit longer-dated options harder. If IV is high and you want time, a longer-dated option carries more crush risk. Shorter-dated options are mostly a delta/gamma bet.", "src": "Kaeppel Ch.6, PDF p.91–94", "quote": "“Changes in volatility have a greater effect on the prices of longer-term options than on the prices of shorter-term options.” (p.91)"}, {"id": "C12", "sec": "(c) Options structure: IV, probability, strike/delta, DTE, spreads", "rule": "Liquidity and price discipline. Trade only tight-spread, high-volume chains (SPY/QQQ qualify). Default to limits: “get in at your price, get out at the market.” Use a market order only when the move is happening now and you're confident. Never buy market-on-open into a gap.", "src": "Kaeppel Ch.9, PDF p.125–129; Ch.10, PDF p.142", "quote": "“Get in at your price, get out at the market.” (p.127) / “If you expect a particular price movement and expect it to start right now, you have no reason to use a limit order.” (p.129)"}, {"id": "C13", "sec": "(c) Options structure: IV, probability, strike/delta, DTE, spreads", "rule": "Pre/post-market: limit orders only. Thin books, wide spreads, and gaps can blow through fills.", "src": "After-Hours Trader PDF p.32, p.210", "quote": "“When you place an order in the after-hours market, you must use a limit order” (p.32)"}, {"id": "C14", "sec": "(c) Options structure: IV, probability, strike/delta, DTE, spreads", "rule": "Short options deep ITM near expiry get assigned. Close them before expiry (matters for spreads on SPY, which is American-style).", "src": "Kaeppel Ch.9, PDF p.122–123", "quote": "“traders who are short an in-the-money option near expiration are best advised to close that position before expiration” (p.122)"}, {"id": "C15", "sec": "(c) Options structure: IV, probability, strike/delta, DTE, spreads", "rule": "Butterfly wings under $0.25 don't hedge anything. Skip lottery wings.", "src": "Chen & Sebastian Ch.13, PDF p.186", "quote": "“Options that are worth less than $0.25 do not hedge anything.”"}, {"id": "D1", "sec": "(d) Exits, stops, targets", "rule": "Every trade has its stop defined before entry. Put it where the trade idea is wrong (a structural level), not at a random % in the noise. On intraday SPY, the stop is the underlying level (VWAP close, VA edge, failure-test extreme). The option's −30–40% is a backstop. [project]", "src": "Grimes Ch.8–9, PDF p.217–218, p.239; Chen Ch.13, PDF p.187", "quote": "“every trade, without exception, has a precise initial risk point defined at the time of entry.” (Grimes p.218)"}, {"id": "D2", "sec": "(d) Exits, stops, targets", "rule": "Stops not too close. They must sit outside normal noise. Initial stops are often ≥ 2 ATR on the trading time frame.", "src": "Grimes Ch.8, PDF p.217–218", "quote": "“[it is] unusual to set an initial stop that is less than two Average True Ranges (ATRs) from the current price, and the initial stop may sometimes be more than four ATRs away” (p.218)"}, {"id": "D3", "sec": "(d) Exits, stops, targets", "rule": "Scale out at 1R. Take 25–50% off when profit equals the initial risk. Then move the stop on the rest to breakeven.", "src": "Grimes Ch.8, PDF p.219; Aziz Ch.7 Trade Management (part0009_split_001); Zalesky Rule #21, PDF p.6", "quote": "“I usually exit between 25 and 33 percent of the position … at a profit equal to my initial risk” (Grimes) / “I sell 400 shares in the first target, bringing my stop loss to break-even” (Aziz)"}, {"id": "D4", "sec": "(d) Exits, stops, targets", "rule": "Minimum 2:1 reward-to-risk to the first logical target, or skip the trade.", "src": "Aziz Ch.3 (part0005_split_000), Rule 5", "quote": "“The minimum win:lose ratio for me is 2:1.”"}, {"id": "D5", "sec": "(d) Exits, stops, targets", "rule": "Targets at structure: next S/R, VWAP, opposite VA edge, prior-day H/L, and session H/L. Place profit orders just inside visible levels.", "src": "Grimes Ch.8, PDF p.220; Aziz Ch.7; MarketWebs p.3", "quote": "“it probably makes sense to tighten the orders up a little bit and bring them inside the swings.” (Grimes p.220)"}, {"id": "D6", "sec": "(d) Exits, stops, targets", "rule": "Time stop. If the trade isn't working within its expected window (failure test: 1–3 bars), get out. Stagnation = exit.", "src": "Grimes PDF p.145; Zalesky Rule #16, PDF p.5", "quote": "“IF YOUR TRADE IS NOT GOING ANYWHERE IN A GIVEN TIMEFRAME, IT’S TIME TO EXIT.” (Zalesky)"}, {"id": "D7", "sec": "(d) Exits, stops, targets", "rule": "Never let a winner turn into a loser.", "src": "Zalesky Rule #4, PDF p.3", "quote": "“NEVER TURN A WINNER INTO A LOSER.”"}, {"id": "D8", "sec": "(d) Exits, stops, targets", "rule": "Biggest loser ≤ biggest winner of the day.", "src": "Zalesky Rule #5, PDF p.4", "quote": "“YOUR BIGGEST LOSER CAN’T EXCEED YOUR BIGGEST WINNER.”"}, {"id": "D9", "sec": "(d) Exits, stops, targets", "rule": "First loss is the best loss. Never average down. Never scale out of losers; exit the whole position.", "src": "Zalesky Rules #11, #21, PDF p.4, p.6; Aziz Ch.7 Trade Mgmt", "quote": "“You should never scale out of your losers.” (Zalesky p.6) / “averaging down a losing trade is a recipe for wiping out your account” (Aziz)"}, {"id": "D10", "sec": "(d) Exits, stops, targets", "rule": "Don't hold out for the last dollar on short premium (verticals: take 60–80% of max).", "src": "Kaeppel Ch.16, PDF p.213; Chen Ch.10 Table 10.1, PDF p.142", "quote": "“You generally should not hold out for the last dollar.” (Kaeppel p.213)"}, {"id": "D11", "sec": "(d) Exits, stops, targets", "rule": "De-risk when you hit loss limits, the regime changes and you have no read, the model isn't working, or targets are hit. Go flat before a trip.", "src": "Chen & Sebastian Ch.12, PDF p.171", "quote": "“The market environment has changed and you don’t have a read on the new environment.”"}, {"id": "E1", "sec": "(e) Sizing and discipline", "rule": "Book sizing (for reference): the books cap risk at 1–2% of equity per trade (Aziz, Chen, Candlestick Bible). Grimes calls <1% conservative and ≥3% extremely aggressive. Atlas's chosen override: $250–400 premium per trade, with the stop (D1) defining the real loss. Recorded once; no further warnings per Atlas.", "src": "Aziz Ch.3 (part0005_split_000/001); Chen Ch.3, PDF p.53; Grimes Ch.9, PDF p.241; CTB PDF p.135", "quote": "“The absolute maximum a trader should risk on any trade is 2% of his or her account equity.” (Aziz)"}, {"id": "E2", "sec": "(e) Sizing and discipline", "rule": "Equal risk per trade. Size so each loss is about the same $ (there's no \"low-risk\" trade). For options: contracts = $ risk ÷ (entry − stop price of the option).", "src": "Grimes Ch.6, PDF p.149; Aziz Ch.3 3-step", "quote": "“trades should be sized so that every loss is equivalent; there is no such thing as a ‘low risk’ trade.”"}, {"id": "E3", "sec": "(e) Sizing and discipline", "rule": "Cut size after 2 straight losers. Restore it after 2 straight winners.", "src": "Zalesky Rule #3, PDF p.3", "quote": "“If I have two losing trades in a row, I always lower my trade size down to a one lot.”"}, {"id": "E4", "sec": "(e) Sizing and discipline", "rule": "Daily and monthly stop-trading limits. Zalesky's students had a daily $ loss limit, after which they shut down. Chen stops for the month at −6%. [project: daily stop = 2 losing trades or the day's loss cap, whichever comes first]", "src": "Zalesky PDF p.4; Chen Ch.3, PDF p.53", "quote": "“Once you reach the $500 loss limit, you must turn your PC off and call it a day.” (Zalesky)"}, {"id": "E5", "sec": "(e) Sizing and discipline", "rule": "Kelly only at half (or less). Full Kelly is too aggressive when its inputs are estimated.", "src": "Chan Ch.6, PDF p.120, p.127; Grimes Ch.9, PDF p.240", "quote": "“traders prefer to cut this recommended leverage in half for safety. This is called ‘half-Kelly’ betting.” (Chan p.120)"}, {"id": "E6", "sec": "(e) Sizing and discipline", "rule": "Written plan: strategies, entry criteria, profit exit, loss exit. Follow it. Master one setup before adding others.", "src": "Kaeppel Ch.10 Summary, PDF p.142; Aziz Ch.7 (part0009_split_009); Zalesky #6, #22", "quote": "“Develop a plan for trading options: • What strategies will I use? • What criteria will I use to enter … exit with a profit … exit with a loss?” (Kaeppel)"}, {"id": "E7", "sec": "(e) Sizing and discipline", "rule": "Validate before you trust: simple rules, few parameters, out-of-sample or paper test, and include spreads/fees.", "src": "Chan Ch.2–3, PDF p.47–48, p.75–77, p.89", "quote": "“Simple models are often the ones that will stand the test of time.” (p.48)"}, {"id": "E8", "sec": "(e) Sizing and discipline", "rule": "Don't hesitate once the setup is there. Don't chase news. Act on the plan; news on TV is “history.”", "src": "Zalesky Rules #13, #23, PDF p.5–6", "quote": "“DON’T PROCRASTINATE. DON’T HESITATE. IF YOU DO, YOU WILL LOSE.”"}, {"id": "E9", "sec": "(e) Sizing and discipline", "rule": "Hit singles, not home runs. Be consistent, make a little every day.", "src": "Zalesky Rules #18–19, PDF p.5", "quote": "“HIT SINGLES NOT HOME RUNS.”"}, {"id": "E10", "sec": "(e) Sizing and discipline", "rule": "Cash is a position. Not trading when there's no edge beats forcing trades.", "src": "Chen & Sebastian Ch.12, PDF p.164–165; After-Hours Trader PDF p.149", "quote": "“Many people have found they are most profitable when they trade the least.” (AHT p.149)"}, {"id": "E11", "sec": "(e) Sizing and discipline", "rule": "Discipline beats discretion once tested (quant lesson).", "src": "Narang, Inside the Black Box 3e (excerpt) Ch.1 §1.3, PDF p.30", "quote": "“A significant driver of failure is a lack of discipline.”"}], "stocksInfo": [{"id": "F1", "rule": "Multi-year sales runway: products with room for a sizable increase in sales for several years", "metric": "revYoY > 0 for 3 yrs and/or analyst 3–5y sales growth ≥ 10% [project]", "src": "Fisher, Common Stocks and Uncommon Profits", "cite": "PDF p.75 (Point 1)", "quote": "“Does the company have products or services with sufficient market potential to make possible a sizable increase in sales for at least several years?”", "summary": false}, {"id": "F2", "rule": "Worthwhile, improving profit margin", "metric": "opMargin ≥ industry median and not falling YoY [project]", "src": "Fisher", "cite": "PDF p.90–91 (Points 5–6)", "quote": "“Does the company have a worthwhile profit margin?” / “What is the company doing to maintain or improve profit margins?”", "summary": false}, {"id": "F3", "rule": "R&D effectiveness relative to size", "metric": "R&D/sales vs peers (qualitative unless data exists)", "src": "Fisher", "cite": "PDF p.82 (Point 3)", "quote": "“How effective are the company’s research and development efforts in relation to its size?”", "summary": false}, {"id": "F4", "rule": "Growth shouldn't need heavy equity financing", "metric": "Share count change ≤ +2%/yr (same as rule 10)", "src": "Fisher", "cite": "PDF p.102 (Point 13)", "quote": "“will the growth of the company require sufficient equity financing so that the larger number of shares then outstanding will largely cancel the existing stockholders’ benefit”", "summary": false}, {"id": "F5", "rule": "Candid management that talks about bad news too, and integrity", "metric": "Qualitative flag (restatements, guidance withdrawals, SEC actions)", "src": "Fisher", "cite": "PDF p.103, p.105 (Points 14–15)", "quote": "“Does the company have a management of unquestionable integrity?”", "summary": false}, {"id": "F6", "rule": "Long-range profit outlook", "metric": "Qualitative", "src": "Fisher", "cite": "PDF p.101 (Point 12)", "quote": "“Does the company have a short-range or long-range outlook in regard to profits?”", "summary": false}, {"id": "F7", "rule": "Sell only on (a) a purchase mistake, (b) the company no longer meeting the 15 points as well as it did at purchase, or (c) a clearly better use of the money. Otherwise hold.", "metric": "Sell trigger = falling below buy-score thresholds, not price alone", "src": "Fisher", "cite": "PDF p.134–135, p.141", "quote": "“If the job has been correctly done when a common stock is purchased, the time to sell it is—almost never.” (p.141)", "summary": false}, {"id": "F8", "rule": "Don't buy promotional, pre-revenue companies", "metric": "Exclude market cap < $300M with no revenue [project]", "src": "Fisher", "cite": "PDF p.151 (Don't #1)", "quote": "“Don’t buy into promotional companies.”", "summary": false}, {"id": "F9", "rule": "Don't quibble over small price differences on a great company", "metric": "Use limit orders near the market, not far below it", "src": "Fisher", "cite": "PDF p.160 (Don't #5)", "quote": "“Don’t quibble over eighths and quarters.”", "summary": false}, {"id": "L1", "rule": "Classify every stock into one of six types (slow grower, stalwart, fast grower, cyclical, asset play, turnaround) and apply that type's playbook. Stalwarts: take 30–50% gains. Cyclicals: timing is everything.", "metric": "Category tag from EPS growth/sector", "src": "Lynch, One Up On Wall Street", "cite": "PDF p.7", "quote": "“Stalwarts: Grows at 1.5X to 2X of GDP … Buy for 30 to 50 % gain and sell.” / “Fast Growers: Small, aggressive new enterprises. Grow at 20-25%.”", "summary": true}, {"id": "L2", "rule": "Dividend-adjusted PEG: (long-term EPS growth + dividend yield) ÷ P/E. Below 1 = poor, ~1.5 = OK, 2 or more = better.", "metric": "(epsGrowth5y + divYield)/pe ≥ 1.5 [author bands]", "src": "Lynch", "cite": "PDF p.14", "quote": "“Long-Term earnings growth rate Plus Dividend Yield)/P-E ratio < 1 : Poor; =1.5: OK; and >=2: Better.”", "summary": true}, {"id": "L3", "rule": "Net cash per share (cash minus long-term debt) puts a floor under the price", "metric": "(cash − LT debt)/shares > 0 = plus", "src": "Lynch", "cite": "PDF p.14", "quote": "“Cash Position: Cash per Share net of long term debt … Provides floor to the stock price.”", "summary": true}, {"id": "L4", "rule": "Two-minute drill: write a 2-minute thesis before buying", "metric": "Required thesis field", "src": "Lynch", "cite": "PDF p.12", "quote": "“Before buying a stock, you should be able to give a two minute monologue that even a child can understand”", "summary": true}, {"id": "L5", "rule": "Plus signs: spinoffs with insider buying, and low institutional ownership/analyst coverage", "metric": "insiderBuying, instOwn low = plus", "src": "Lynch", "cite": "PDF p.8", "quote": "“Get more excited, if you see heavy insider buying among the new officers and directors.” / “THE INSTITUTIONS DON’T OWN IT, AND THE ANALYSTS DON’T FOLLOW IT”", "summary": true}, {"id": "M1", "rule": "Twin engines: earnings growth and a rising multiple", "metric": "EPS growth ≥ 15% with P/E below its 5y median [project]", "src": "Mayer, 100 Baggers", "cite": "PDF p.24, p.106", "quote": "“the importance of growth dynamics as the ‘twin engines’ driving 100-bagger status”", "summary": true}, {"id": "M2", "rule": "High ROE/ROIC that can be reinvested at high rates, without heavy leverage", "metric": "roic ≥ 15% (rule 1) and low payout / high reinvestment [project]", "src": "Mayer", "cite": "PDF p.111, p.151", "quote": "“finding businesses with a high return on capital that can reinvest at high rates for an extended period” (p.151)", "summary": true}, {"id": "M3", "rule": "Owner-operators: significant insider ownership", "metric": "insiderOwn ≥ 10% [project]", "src": "Mayer", "cite": "PDF p.36, p.113", "quote": "“Companies led by owner-operators tend to make better decisions and avoid risky bet-the-company strategies.” (p.113)", "summary": true}, {"id": "M4", "rule": "Durable moat, with high gross margins vs peers as evidence", "metric": "grossMargin ≥ industry 75th percentile [project]", "src": "Mayer", "cite": "PDF p.54, p.141", "quote": "“A truly great business must have an enduring ‘moat’ that protects excellent returns on invested capital.” (p.54, quoting Buffett)", "summary": true}, {"id": "M5", "rule": "Buybacks count only below intrinsic value and only if the share count actually falls", "metric": "Share count change < 0 with FCF yield ≥ 3%", "src": "Mayer", "cite": "PDF p.51–52", "quote": "“advisable only when a company has excess funds and its stock trades below intrinsic value” (p.52)", "summary": true}, {"id": "M6", "rule": "Buy right and hold on (coffee-can mindset); selling too early costs the biggest gains", "metric": "Holding-period rule for core names", "src": "Mayer", "cite": "PDF p.14, p.68, p.106", "quote": "“Selling too early can significantly reduce overall gains” (p.106)", "summary": true}]};
