  // ---------- SPY playbook ----------
  function viewSpy() {
    const root = document.getElementById("spy-root"); if (!root) return;
    const rg = (window.SCORES && window.SCORES.combined && window.SCORES.combined.regime) || {};
    const step = (n, title, body) => `<section class="nx-step"><div class="nx-step-n">${n}</div><div class="nx-step-body"><h3>${title}</h3>${body}</div></section>`;
    const li = (txt, ids) => `<li>${txt} ${ids ? chip(ids) : ""}</li>`;
    root.innerHTML = `<header class="nx-head"><p class="eyebrow">Research only · all times Central</p><h2>SPY playbook (0–14 DTE)</h2>
        <p class="nx-lead">A step-by-step plan for short-dated SPY and QQQ options, built from your options and technical-analysis books. Tap any small rule chip to see the book and the quote.</p>
        <div class="nx-kv">${rg.spyClose ? `<span>SPY last close <b>${money(rg.spyClose)}</b></span><span>200-day <b>${money(rg.spySma200)}</b></span>` : ""}<span>Market regime <b>${esc(rg.level || "n/a")}</b></span>${(rg.reasons || []).length ? `<span class="nx-dim">${esc(rg.reasons.join("; "))}</span>` : ""}</div></header>
      ${NO_CHAIN}
      ${isFriday() ? `<div class="nx-banner is-warn"><b>It’s Friday.</b> Close short-dated long calls and puts before the bell instead of carrying them over the weekend. ${chip("C6")}</div>` : ""}
      ${step(1, "Before the open", `<ul>
        ${li("<b>Check option prices.</b> Low VIX that’s falling: buying calls or puts outright is fine. High or spiking VIX: use a debit spread that sells the pricier out-of-the-money leg. Never buy far out-of-the-money puts in a panic.", "A1 A3 A4 C8")}
        ${li("<b>Know the event times</b> (CPI, Fed, jobs, mega-cap earnings). Be flat into the release unless the event is the trade.", "A5")}
        ${li("<b>Mark your levels before 8:30:</b> prior-day high, low and close, yesterday’s value area high and low, the busiest price (POC), the overnight high and low, round numbers, and the daily or 60-minute trend.", "B9 B10 A6")}
      </ul>`)}
      ${step(2, "First hour (8:30–9:30): classify the day", `<ul>
        ${li("No new entries from 8:30 to 8:40. The first 15 minutes set the opening range, and the first hour sets the day’s reference box.", "B6")}
        ${li("<b>Opens outside yesterday’s value and holds:</b> trend bias, so trade with it.", "A8")}
        ${li("<b>Opens inside value:</b> expect chop. Fade the edges and target the POC or the other edge.", "A9 B11")}
        ${li("<b>Range stretches past about 2× the first hour:</b> trend day. Stop fading and only buy pullbacks with the trend.", "A7")}
        ${li("A gap that presses through the opening range often trends all day, so don’t fight it.", "B5")}
      </ul>`)}
      ${step(3, "Take only these setups", `<ol class="nx-setups">
        ${li("<b>VWAP hold or reclaim.</b> Go long above VWAP after a retest holds, with a stop on a 5-minute close back through VWAP. Puts are the mirror image.", "B7")}
        ${li("<b>Failure test at a level.</b> Price pokes through yesterday’s high or low, a first-hour extreme, or a value edge, then closes back inside. Enter on that close with a stop just past the extreme. It should work within 1–3 bars.", "B3")}
        ${li("<b>Trend pullback (trend days only).</b> Buy a hold of the 9 or 20 EMA or VWAP after a strong leg. Skip it if support has been tested 3+ times. After the 3rd push, take profits and don’t start new trades.", "B1 B2 A10")}
        ${li("<b>Compression breakout.</b> Enter inside a tight range or inside bars just under a level. Otherwise assume SPY reverts toward the middle.", "A11 B4")}
      </ol>
      <p class="nx-note">Candles only confirm at one of your levels, ideally on the 15- or 60-minute chart. Every trigger needs at least 2-to-1 room to the next level, or you skip it. ${chip("B12 B13 D4")}</p>`)}
      ${step(4, "Pick the contract", `<ul>
        ${li("<b>Delta 0.50–0.70</b> (at the money to one strike in the money), not cheap out-of-the-money strikes. The higher the IV, the deeper in the money you go.", "C1 C2")}
        ${li("<b>0DTE:</b> only for a move happening now. Get out early, with no 0DTE holds past about 2:30 PM CT (our own rule, since the books predate 0DTE).", "C4")}
        ${li("<b>1–3 DTE:</b> intraday to overnight. <b>For a 1–3 day swing, use 7–14 DTE</b> (about 3× the planned hold).", "C5")}
        ${li("<b>Budget $250–400.</b> If one 0.50+ delta contract costs more than $400, or IV is rich, use a debit spread (buy the at-the-money strike, sell the pricier out-of-the-money one).", "C8")}
        ${li("<b>Limit orders by default:</b> get in at your price, get out at the market. Never buy market-on-open. Use limit orders only before and after the regular session.", "C12 C13")}
      </ul>`)}
      ${step(5, "Exits", `<ul>
        ${li("<b>Stop = the price level that proves you wrong</b> (a VWAP close, a value edge, or a failure-test extreme). Keep about −30–40% of premium as a backstop. Decide both before you enter.", "D1 D2")}
        ${li("<b>At +1R</b> (profit equal to your planned loss), sell 1/3 to 1/2 and move the stop to breakeven. Never let a winner turn into a loser.", "D3 D7")}
        ${li("Targets: the next level, the opposite value edge, POC or VWAP, or the prior-day high or low. Set limits just inside them.", "D5")}
        ${li("<b>Time stop:</b> if it isn’t working in the expected window, get out. Exit losers all at once and never average down.", "D6 D9")}
      </ul>`)}
      ${step(6, "Discipline", `<ul>
        ${li("Risk the same dollars on every trade, within your $250–400 band.", "E2")}
        ${li("<b>After 2 losers in a row:</b> drop to the smallest size or stop for the day. Restore size after 2 winners.", "E3 E4")}
        ${li("The day’s biggest loss can’t be bigger than its biggest win.", "D8")}
        ${li("Cash is a position. A choppy day with no clean trigger is a no-trade day. Master one setup first.", "E10 E6")}
      </ul>`)}
      <p class="nx-foot">From SPY-PLAYBOOK.md and BOOKS-RULES-OPTIONS.md (Kaeppel, Chen &amp; Sebastian, Grimes, Candlestick Trading Bible, CBOT Market Profile, MarketWebs, Aziz, Zalesky, Chan). Research only.</p>`;
  }

